/**
 * Browser entry of the Android device panel: the right sidebar tab and its Remote.
 * Generated by ttoken/apply-brand.mjs from ttoken/device/src/client/index.ts; edit it there.
 */

import type { Context } from '@deepseek-ai/cordis'
import remote from '@deepseek-ai/dsh-experimental-android-device/remote'
import { mountDevicePanel } from './mount.ts'

export { inject } from './mount.ts'
export type { DevicePanelKey } from './locales.ts'
export type { DevicePanelInjected, DevicePanelProps } from './DevicePanel.tsx'

/**
 * Mount the device panel Remote and its UI.
 * @param ctx - browser plugin context.
 * @returns the disposer that withdraws the UI, then the Remote.
 */
export async function apply(ctx: Context): Promise<() => Promise<void>> {
  return await mountDevicePanel(ctx, remote)
}
